"""Recursive-descent parser for the minisql SELECT grammar.

``parse(sql)`` returns a :class:`minisql.ast.Select`.  All problems with the
query are reported as :class:`minisql.errors.QueryError`.
"""

from typing import List, Optional

from .ast import (
    Between,
    Binary,
    Call,
    Column,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Select,
    SelectItem,
    Star,
    Unary,
)
from .errors import QueryError
from .lexer import (
    EOF,
    IDENT,
    KEYWORD,
    NUMBER,
    OP,
    STRING,
    Token,
    line_column,
    tokenize,
)

_COMPARISON_OPS = frozenset(("=", "!=", "<>", "<", "<=", ">", ">="))
_ADDITIVE_OPS = frozenset(("+", "-", "||"))
_MULTIPLICATIVE_OPS = frozenset(("*", "/"))
_PREDICATE_KEYWORDS = frozenset(("IN", "BETWEEN", "LIKE"))


class Parser:
    """A recursive-descent parser over the tokens from :mod:`minisql.lexer`."""

    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # ------------------------------------------------------------------
    # Token helpers

    def peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index < 0:
            index = 0
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def advance(self) -> Token:
        token = self.peek()
        if token.kind != EOF:
            self.pos += 1
        return token

    def previous(self) -> Token:
        if self.pos == 0:
            return self.tokens[0]
        return self.tokens[self.pos - 1]

    @staticmethod
    def describe(token: Token) -> str:
        if token.kind == EOF:
            return "end of input"
        return repr(token.text)

    def error(self, message: str, token: Optional[Token] = None):
        token = self.peek() if token is None else token
        line, column = line_column(self.sql, token.start)
        raise QueryError(
            "syntax error: %s at line %d, column %d" % (message, line, column)
        )

    def text(self, start: Token, end: Optional[Token] = None) -> str:
        """Exact source text between two tokens (inclusive), stripped."""
        if end is None:
            end = self.previous()
        return self.sql[start.start : end.end].strip()

    # ------------------------------------------------------------------
    # Token predicates

    def check_keyword(self, word: str) -> bool:
        token = self.peek()
        return token.kind == KEYWORD and token.value == word

    def match_keyword(self, word: str) -> Optional[Token]:
        if self.check_keyword(word):
            return self.advance()
        return None

    def expect_keyword(self, word: str) -> Token:
        if not self.check_keyword(word):
            self.error(
                "expected %s, got %s" % (word, self.describe(self.peek()))
            )
        return self.advance()

    def check_op(self, value: str) -> bool:
        token = self.peek()
        return token.kind == OP and token.value == value

    def match_op(self, value: str) -> Optional[Token]:
        if self.check_op(value):
            return self.advance()
        return None

    def expect_op(self, value: str) -> Token:
        if not self.check_op(value):
            self.error(
                "expected %r, got %s" % (value, self.describe(self.peek()))
            )
        return self.advance()

    # ------------------------------------------------------------------
    # Query structure

    def parse(self) -> Select:
        if self.peek().kind == EOF:
            self.error("empty query")

        self.expect_keyword("SELECT")
        distinct = self.match_keyword("DISTINCT") is not None
        columns = self.parse_select_columns()
        self.expect_keyword("FROM")
        table = self.parse_table_name()

        where = None
        if self.match_keyword("WHERE"):
            where = self.parse_expr()

        group_by = []
        if self.match_keyword("GROUP"):
            self.expect_keyword("BY")
            group_by = self.parse_expr_list()

        having = None
        if self.match_keyword("HAVING"):
            having = self.parse_expr()

        order_by = []
        if self.match_keyword("ORDER"):
            self.expect_keyword("BY")
            order_by = self.parse_order_items()

        limit = None
        offset = None
        if self.match_keyword("LIMIT"):
            limit = self.parse_limit_value("LIMIT")
            if self.match_keyword("OFFSET"):
                offset = self.parse_limit_value("OFFSET")
        elif self.check_keyword("OFFSET"):
            self.error("OFFSET requires LIMIT")

        if self.match_op(";"):
            pass

        if self.peek().kind != EOF:
            self.error(
                "unexpected %s after query" % self.describe(self.peek())
            )

        return Select(
            columns=columns,
            distinct=distinct,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def parse_select_columns(self) -> List[SelectItem]:
        # ``*`` is only valid as the whole select list.
        if self.check_op("*"):
            star = self.advance()
            return [SelectItem(Star(text=star.text))]

        columns = [self.parse_select_column()]
        while self.match_op(","):
            columns.append(self.parse_select_column())
        return columns

    def parse_select_column(self) -> SelectItem:
        expr = self.parse_expr()

        alias = None
        if self.match_keyword("AS"):
            token = self.peek()
            if token.kind != IDENT:
                self.error(
                    "expected an alias name after AS, got %s"
                    % self.describe(token)
                )
            self.advance()
            alias = token.value
        elif self.peek().kind == IDENT:
            alias = self.advance().value

        return SelectItem(expr, alias)

    def parse_table_name(self) -> str:
        token = self.peek()
        if token.kind != IDENT:
            self.error(
                "expected a table name after FROM, got %s"
                % self.describe(token)
            )
        self.advance()
        return token.value

    def parse_expr_list(self) -> List[object]:
        items = [self.parse_expr()]
        while self.match_op(","):
            items.append(self.parse_expr())
        return items

    def parse_order_items(self) -> List[OrderItem]:
        items = []
        while True:
            expr = self.parse_expr()
            desc = False
            if self.match_keyword("ASC"):
                pass
            elif self.match_keyword("DESC"):
                desc = True
            items.append(OrderItem(expr, desc))
            if not self.match_op(","):
                break
        return items

    def parse_limit_value(self, clause: str) -> int:
        token = self.peek()
        if token.kind == NUMBER:
            if isinstance(token.value, int) and not isinstance(token.value, bool):
                self.advance()
                return token.value
            self.error(
                "%s must be an integer, got %s" % (clause, token.text)
            )
        if token.kind == OP and token.value in ("-", "+"):
            self.error(
                "%s must be a non-negative integer, got %r"
                % (clause, token.value)
            )
        self.error(
            "expected a non-negative integer after %s, got %s"
            % (clause, self.describe(token))
        )

    # ------------------------------------------------------------------
    # Expressions, lowest precedence first

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        start = self.peek()
        left = self.parse_and()
        while self.match_keyword("OR"):
            right = self.parse_and()
            left = Binary("OR", left, right, text=self.text(start))
        return left

    def parse_and(self):
        start = self.peek()
        left = self.parse_not()
        while self.match_keyword("AND"):
            right = self.parse_not()
            left = Binary("AND", left, right, text=self.text(start))
        return left

    def parse_not(self):
        start = self.peek()
        if self.check_keyword("NOT"):
            self.advance()
            operand = self.parse_not()
            return Unary("NOT", operand, text=self.text(start))
        return self.parse_comparison()

    def parse_comparison(self):
        start = self.peek()
        left = self.parse_additive()

        token = self.peek()
        node = None

        if token.kind == OP and token.value in _COMPARISON_OPS:
            op = self.advance().value
            right = self.parse_additive()
            node = Binary(op, left, right)

        elif token.kind == KEYWORD and token.value == "IS":
            self.advance()
            negated = self.match_keyword("NOT") is not None
            if not self.check_keyword("NULL"):
                self.error(
                    "expected NULL after IS%s, got %s"
                    % (" NOT" if negated else "", self.describe(self.peek()))
                )
            self.advance()
            node = IsNull(left, negated)

        elif token.kind == KEYWORD and token.value in _PREDICATE_KEYWORDS:
            node = self.parse_predicate(left, False)

        elif token.kind == KEYWORD and token.value == "NOT":
            self.advance()
            following = self.peek()
            if not (
                following.kind == KEYWORD
                and following.value in _PREDICATE_KEYWORDS
            ):
                self.error(
                    "expected IN, BETWEEN, or LIKE after NOT, got %s"
                    % self.describe(following)
                )
            node = self.parse_predicate(left, True)

        if node is None:
            return left

        node.text = self.text(start)

        if self.starts_comparison():
            self.error("comparison operators cannot be chained")
        return node

    def parse_predicate(self, left, negated: bool):
        token = self.peek()
        keyword = token.value
        self.advance()

        if keyword == "IN":
            self.expect_op("(")
            items = []
            if self.check_op(")"):
                self.error("IN requires at least one expression")
            while True:
                items.append(self.parse_expr())
                if self.match_op(","):
                    if self.check_op(")"):
                        self.error("expected an expression after ',' in IN list")
                    continue
                break
            self.expect_op(")")
            return InList(left, items, negated)

        if keyword == "BETWEEN":
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            return Between(left, low, high, negated)

        # LIKE
        pattern = self.parse_additive()
        return Like(left, pattern, negated)

    def starts_comparison(self) -> bool:
        token = self.peek()
        if token.kind == OP and token.value in _COMPARISON_OPS:
            return True
        if token.kind == KEYWORD:
            if token.value in ("IS",) + tuple(_PREDICATE_KEYWORDS):
                return True
            if token.value == "NOT":
                following = self.peek(1)
                return (
                    following.kind == KEYWORD
                    and following.value in _PREDICATE_KEYWORDS
                )
        return False

    def parse_additive(self):
        start = self.peek()
        left = self.parse_multiplicative()
        while True:
            token = self.peek()
            if token.kind != OP or token.value not in _ADDITIVE_OPS:
                break
            self.advance()
            right = self.parse_multiplicative()
            left = Binary(token.value, left, right, text=self.text(start))
        return left

    def parse_multiplicative(self):
        start = self.peek()
        left = self.parse_unary()
        while True:
            token = self.peek()
            if token.kind != OP or token.value not in _MULTIPLICATIVE_OPS:
                break
            self.advance()
            right = self.parse_unary()
            left = Binary(token.value, left, right, text=self.text(start))
        return left

    def parse_unary(self):
        if self.check_op("-"):
            start = self.advance()
            operand = self.parse_unary()
            return Unary("-", operand, text=self.text(start))
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()

        if token.kind == NUMBER:
            self.advance()
            return Literal(token.value, text=token.text)

        if token.kind == STRING:
            self.advance()
            return Literal(token.value, text=token.text)

        if token.kind == IDENT:
            following = self.peek(1)
            if following.kind == OP and following.value == "(":
                return self.parse_call()
            self.advance()
            return Column(token.value, text=token.text)

        if token.kind == KEYWORD:
            if token.value == "NULL":
                self.advance()
                return Literal(None, text=token.text)
            if token.value == "TRUE":
                self.advance()
                return Literal(True, text=token.text)
            if token.value == "FALSE":
                self.advance()
                return Literal(False, text=token.text)
            self.error(
                "expected an expression, got %s" % self.describe(token)
            )

        if token.kind == OP and token.value == "(":
            start = self.advance()
            expr = self.parse_expr()
            end = self.expect_op(")")
            expr.text = self.text(start, end)
            return expr

        self.error("expected an expression, got %s" % self.describe(token))

    def parse_call(self) -> Call:
        start = self.peek()
        name = self.advance()  # IDENT
        self.expect_op("(")

        args = []
        if self.check_op("*"):
            star = self.advance()
            args.append(Star(text=star.text))
            self.expect_op(")")
        else:
            if not self.check_op(")"):
                while True:
                    args.append(self.parse_expr())
                    if self.match_op(","):
                        if self.check_op(")"):
                            self.error(
                                "expected an expression after ',' in function call"
                            )
                        continue
                    break
            self.expect_op(")")

        return Call(name.value.lower(), args, text=self.text(start))


def parse(sql: str) -> Select:
    """Parse a single SELECT statement into an :class:`minisql.ast.Select`."""
    return Parser(sql).parse()


__all__ = ["Parser", "parse"]

"""Tests for the minisql tokenizer and parser."""

import unittest

from minisql.ast import (
    Between,
    Binary,
    Call,
    Column,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Select,
    SelectItem,
    Star,
    Unary,
)
from minisql.errors import QueryError
from minisql.lexer import EOF, IDENT, KEYWORD, NUMBER, OP, STRING, tokenize
from minisql.parser import parse


class LexerTests(unittest.TestCase):
    def test_keywords_are_case_insensitive_but_text_is_preserved(self):
        tokens = tokenize("select From WHERE Desc")
        self.assertEqual(
            [(tok.kind, tok.value, tok.text) for tok in tokens[:-1]],
            [
                (KEYWORD, "SELECT", "select"),
                (KEYWORD, "FROM", "From"),
                (KEYWORD, "WHERE", "WHERE"),
                (KEYWORD, "DESC", "Desc"),
            ],
        )
        self.assertEqual(tokens[-1].kind, EOF)

    def test_non_keyword_identifiers(self):
        tokens = tokenize("_a A1 lower countx")
        self.assertEqual([tok.kind for tok in tokens[:-1]], [IDENT] * 4)
        self.assertEqual(
            [tok.value for tok in tokens[:-1]], ["_a", "A1", "lower", "countx"]
        )

    def test_number_forms(self):
        tokens = tokenize("42 2.5 .5 2.")
        self.assertEqual(
            [(tok.kind, tok.value, tok.text) for tok in tokens[:-1]],
            [
                (NUMBER, 42, "42"),
                (NUMBER, 2.5, "2.5"),
                (NUMBER, 0.5, ".5"),
                (NUMBER, 2.0, "2."),
            ],
        )

    def test_single_quoted_strings(self):
        tokens = tokenize("'abc' 'it''s' ''")
        self.assertEqual([tok.kind for tok in tokens[:-1]], [STRING] * 3)
        self.assertEqual(
            [tok.value for tok in tokens[:-1]], ["abc", "it's", ""]
        )
        self.assertEqual(
            [tok.text for tok in tokens[:-1]], ["'abc'", "'it''s'", "''"]
        )

    def test_double_quoted_identifiers(self):
        tokens = tokenize('"unit price" "a""b" ""')
        self.assertEqual([tok.kind for tok in tokens[:-1]], [IDENT] * 3)
        self.assertEqual(
            [tok.value for tok in tokens[:-1]], ["unit price", 'a"b', ""]
        )
        self.assertEqual(
            [tok.text for tok in tokens[:-1]],
            ['"unit price"', '"a""b"', '""'],
        )

    def test_operators_and_punctuation(self):
        tokens = tokenize("= != <> < <= > >= + - * / || ( ) , ;")
        self.assertEqual(
            [tok.value for tok in tokens[:-1]],
            [
                "=",
                "!=",
                "<>",
                "<",
                "<=",
                ">",
                ">=",
                "+",
                "-",
                "*",
                "/",
                "||",
                "(",
                ")",
                ",",
                ";",
            ],
        )
        self.assertTrue(all(tok.kind == OP for tok in tokens[:-1]))

    def test_token_offsets(self):
        tokens = tokenize("  SELECT a ")
        self.assertEqual((tokens[0].start, tokens[0].end), (2, 8))
        self.assertEqual((tokens[1].start, tokens[1].end), (9, 10))
        self.assertEqual((tokens[-1].start, tokens[-1].end), (11, 11))

    def test_unterminated_string(self):
        with self.assertRaises(QueryError):
            tokenize("SELECT 'abc")

    def test_unterminated_quoted_identifier(self):
        with self.assertRaises(QueryError):
            tokenize('SELECT "abc')

    def test_unknown_character(self):
        for sql in ("SELECT a & b", "SELECT a ? b", "SELECT . FROM t"):
            with self.assertRaises(QueryError):
                tokenize(sql)


class ParserStructureTests(unittest.TestCase):
    def test_minimal_select(self):
        self.assertEqual(
            parse("SELECT a FROM t"),
            Select(columns=[SelectItem(Column("a"))], table="t"),
        )

    def test_full_query(self):
        select = parse(
            "SELECT DISTINCT category, COUNT(*) AS n FROM products "
            "WHERE price > 10 GROUP BY category HAVING COUNT(*) > 1 "
            "ORDER BY n DESC LIMIT 5 OFFSET 2;"
        )
        self.assertTrue(select.distinct)
        self.assertEqual(select.table, "products")
        self.assertEqual(
            select.columns,
            [
                SelectItem(Column("category")),
                SelectItem(Call("count", [Star()]), "n"),
            ],
        )
        self.assertEqual(
            select.where, Binary(">", Column("price"), Literal(10))
        )
        self.assertEqual(select.group_by, [Column("category")])
        self.assertEqual(
            select.having,
            Binary(">", Call("count", [Star()]), Literal(1)),
        )
        self.assertEqual(select.order_by, [OrderItem(Column("n"), True)])
        self.assertEqual(select.limit, 5)
        self.assertEqual(select.offset, 2)

    def test_star_select_and_count_star(self):
        select = parse("SELECT * FROM t")
        self.assertEqual(select.columns, [SelectItem(Star())])
        select = parse("SELECT COUNT(*) FROM t")
        self.assertEqual(select.columns, [SelectItem(Call("count", [Star()]))])
        self.assertEqual(select.columns[0].expr.text, "COUNT(*)")

    def test_aliases(self):
        select = parse('SELECT a AS x, b y, c AS "z z" FROM t')
        self.assertEqual(
            select.columns,
            [
                SelectItem(Column("a"), "x"),
                SelectItem(Column("b"), "y"),
                SelectItem(Column("c"), "z z"),
            ],
        )

    def test_function_name_can_be_a_column(self):
        select = parse("SELECT count, COUNT(*) FROM t")
        self.assertEqual(select.columns[0], SelectItem(Column("count")))
        self.assertEqual(
            select.columns[1], SelectItem(Call("count", [Star()]))
        )

    def test_function_names_are_lowercased_and_arguments_kept(self):
        select = parse("SELECT CoAlEsCe(a, b + 1), LOWER(name) FROM t")
        self.assertEqual(
            select.columns,
            [
                SelectItem(
                    Call(
                        "coalesce",
                        [Column("a"), Binary("+", Column("b"), Literal(1))],
                    )
                ),
                SelectItem(Call("lower", [Column("name")])),
            ],
        )

    def test_empty_function_arguments_parse(self):
        select = parse("SELECT f() FROM t")
        self.assertEqual(select.columns, [SelectItem(Call("f", []))])

    def test_quoted_names_preserve_original_case_and_unescape(self):
        select = parse('SELECT "Unit Price", Name FROM "My Table"')
        self.assertEqual(select.table, "My Table")
        self.assertEqual(
            select.columns,
            [SelectItem(Column("Unit Price")), SelectItem(Column("Name"))],
        )

    def test_literals(self):
        select = parse("SELECT 42, 2.5, .5, 2., 'x', NULL, TRUE, FALSE FROM t")
        values = [item.expr.value for item in select.columns]
        self.assertEqual(values, [42, 2.5, 0.5, 2.0, "x", None, True, False])
        self.assertIs(type(values[0]), int)
        self.assertIs(type(values[1]), float)
        self.assertIs(type(values[7]), bool)

    def test_order_by_asc_desc_and_mixed_items(self):
        select = parse("SELECT a FROM t ORDER BY 1, b DESC, c ASC")
        self.assertEqual(
            select.order_by,
            [
                OrderItem(Literal(1), False),
                OrderItem(Column("b"), True),
                OrderItem(Column("c"), False),
            ],
        )

    def test_group_by_multiple_expressions(self):
        select = parse("SELECT a FROM t GROUP BY a, b + 1")
        self.assertEqual(
            select.group_by,
            [Column("a"), Binary("+", Column("b"), Literal(1))],
        )

    def test_limit_and_offset(self):
        select = parse("SELECT a FROM t LIMIT 0")
        self.assertEqual((select.limit, select.offset), (0, None))
        select = parse("SELECT a FROM t LIMIT 10 OFFSET 3")
        self.assertEqual((select.limit, select.offset), (10, 3))

    def test_trailing_semicolon(self):
        self.assertEqual(
            parse("SELECT a FROM t;"),
            Select(columns=[SelectItem(Column("a"))], table="t"),
        )


class PrecedenceTests(unittest.TestCase):
    def expr(self, text):
        return parse("SELECT " + text + " FROM t").columns[0].expr

    def where(self, text):
        return parse("SELECT a FROM t WHERE " + text).where

    def test_or_binds_less_tightly_than_and(self):
        self.assertEqual(
            self.where("a OR b AND c"),
            Binary(
                "OR",
                Column("a"),
                Binary("AND", Column("b"), Column("c")),
            ),
        )

    def test_and_is_left_associative(self):
        self.assertEqual(
            self.where("a AND b AND c"),
            Binary(
                "AND",
                Binary("AND", Column("a"), Column("b")),
                Column("c"),
            ),
        )

    def test_not_binds_tighter_than_and_but_looser_than_comparison(self):
        self.assertEqual(
            self.where("NOT a AND b"),
            Binary("AND", Unary("NOT", Column("a")), Column("b")),
        )
        self.assertEqual(
            self.where("NOT a = b"),
            Unary("NOT", Binary("=", Column("a"), Column("b"))),
        )

    def test_arithmetic_precedence(self):
        self.assertEqual(
            self.expr("a + b * c - d"),
            Binary(
                "-",
                Binary(
                    "+",
                    Column("a"),
                    Binary("*", Column("b"), Column("c")),
                ),
                Column("d"),
            ),
        )

    def test_additive_is_left_associative(self):
        self.assertEqual(
            self.expr("a - b - c"),
            Binary(
                "-",
                Binary("-", Column("a"), Column("b")),
                Column("c"),
            ),
        )

    def test_multiplicative_is_left_associative_and_concat_shares_level(self):
        self.assertEqual(
            self.expr("a / b * c"),
            Binary(
                "*",
                Binary("/", Column("a"), Column("b")),
                Column("c"),
            ),
        )
        self.assertEqual(
            self.expr("a || b || c"),
            Binary(
                "||",
                Binary("||", Column("a"), Column("b")),
                Column("c"),
            ),
        )

    def test_unary_minus_binds_tighter_than_multiplication(self):
        self.assertEqual(
            self.expr("-a * b"),
            Binary("*", Unary("-", Column("a")), Column("b")),
        )
        self.assertEqual(
            self.expr("- -a"),
            Unary("-", Unary("-", Column("a"))),
        )

    def test_parentheses_override_precedence(self):
        self.assertEqual(
            self.expr("(a + b) * c"),
            Binary(
                "*",
                Binary("+", Column("a"), Column("b")),
                Column("c"),
            ),
        )

    def test_comparison_is_non_associative(self):
        with self.assertRaises(QueryError):
            self.where("a = b = c")
        with self.assertRaises(QueryError):
            self.where("a < b IS NULL")
        with self.assertRaises(QueryError):
            self.where("a IN (1) IN (2)")

    def test_comparison_operators(self):
        for op in ("=", "!=", "<>", "<", "<=", ">", ">="):
            self.assertEqual(
                self.where("a %s b" % op),
                Binary(op, Column("a"), Column("b")),
            )


class PredicateTests(unittest.TestCase):
    def where(self, text):
        return parse("SELECT a FROM t WHERE " + text).where

    def test_is_null_and_is_not_null(self):
        self.assertEqual(
            self.where("a IS NULL"), IsNull(Column("a"), False)
        )
        self.assertEqual(
            self.where("a IS NOT NULL"), IsNull(Column("a"), True)
        )

    def test_in_list(self):
        self.assertEqual(
            self.where("a IN (1, b + 1, 'x')"),
            InList(
                Column("a"),
                [
                    Literal(1),
                    Binary("+", Column("b"), Literal(1)),
                    Literal("x"),
                ],
                False,
            ),
        )

    def test_not_in_list(self):
        self.assertEqual(
            self.where("a NOT IN (1, 2)"),
            InList(Column("a"), [Literal(1), Literal(2)], True),
        )

    def test_between_consumes_its_own_and(self):
        self.assertEqual(
            self.where("a BETWEEN 1 AND 2"),
            Between(Column("a"), Literal(1), Literal(2), False),
        )
        self.assertEqual(
            self.where("a NOT BETWEEN 1 AND 2 + 3"),
            Between(
                Column("a"),
                Literal(1),
                Binary("+", Literal(2), Literal(3)),
                True,
            ),
        )

    def test_and_after_between_is_still_a_boolean_and(self):
        self.assertEqual(
            self.where("a BETWEEN 1 AND 2 AND b"),
            Binary(
                "AND",
                Between(Column("a"), Literal(1), Literal(2), False),
                Column("b"),
            ),
        )

    def test_like(self):
        self.assertEqual(
            self.where("a LIKE 'x%'"),
            Like(Column("a"), Literal("x%"), False),
        )
        self.assertEqual(
            self.where("a NOT LIKE 'x_'"),
            Like(Column("a"), Literal("x_"), True),
        )

    def test_not_before_predicate_and_unary_not_together(self):
        self.assertEqual(
            self.where("NOT a IN (1)"),
            Unary(
                "NOT", InList(Column("a"), [Literal(1)], False)
            ),
        )
        self.assertEqual(
            self.where("NOT a BETWEEN 1 AND 2 OR b"),
            Binary(
                "OR",
                Unary(
                    "NOT",
                    Between(Column("a"), Literal(1), Literal(2), False),
                ),
                Column("b"),
            ),
        )

    def test_in_items_are_full_expressions(self):
        self.assertEqual(
            self.where("a IN (b OR c, d AND e)"),
            InList(
                Column("a"),
                [
                    Binary("OR", Column("b"), Column("c")),
                    Binary("AND", Column("d"), Column("e")),
                ],
                False,
            ),
        )


class TextCaptureTests(unittest.TestCase):
    def select_expr(self, text):
        return parse("SELECT " + text + " FROM t").columns[0].expr

    def test_binary_text_is_exact_source_substring(self):
        expr = self.select_expr("price * 2")
        self.assertEqual(expr.text, "price * 2")
        self.assertEqual(expr.left.text, "price")
        self.assertEqual(expr.right.text, "2")

    def test_text_preserves_spacing_and_quotes(self):
        expr = self.select_expr("'it''s' ||  \"A B\"")
        self.assertEqual(expr.text, "'it''s' ||  \"A B\"")
        self.assertEqual(expr.left.text, "'it''s'")
        self.assertEqual(expr.right.text, '"A B"')

    def test_parenthesized_expression_text_includes_parentheses(self):
        expr = self.select_expr("( price + 1 ) * 2")
        self.assertEqual(expr.text, "( price + 1 ) * 2")
        self.assertEqual(expr.left.text, "( price + 1 )")
        self.assertEqual(expr.left.left.text, "price")

    def test_nested_parentheses_text(self):
        expr = self.select_expr("((a))")
        self.assertEqual(expr.text, "((a))")

    def test_call_and_star_text(self):
        expr = self.select_expr("CoUnT( * )")
        self.assertEqual(expr.text, "CoUnT( * )")
        self.assertEqual(expr.args[0].text, "*")

    def test_predicate_text(self):
        where = parse(
            "SELECT a FROM t WHERE x NOT IN ( 1, 2 )"
        ).where
        self.assertEqual(where.text, "x NOT IN ( 1, 2 )")
        where = parse(
            "SELECT a FROM t WHERE x NOT BETWEEN 1 AND 3"
        ).where
        self.assertEqual(where.text, "x NOT BETWEEN 1 AND 3")
        where = parse("SELECT a FROM t WHERE x IS NOT NULL").where
        self.assertEqual(where.text, "x IS NOT NULL")
        where = parse("SELECT a FROM t WHERE x NOT LIKE 'a%'").where
        self.assertEqual(where.text, "x NOT LIKE 'a%'")

    def test_unary_and_boolean_text(self):
        expr = self.select_expr("NOT  a = b")
        self.assertEqual(expr.text, "NOT  a = b")
        self.assertIsInstance(expr, Unary)
        where = parse("SELECT a FROM t WHERE a AND b OR c").where
        self.assertEqual(where.text, "a AND b OR c")


class SyntaxErrorTests(unittest.TestCase):
    def assert_query_error(self, sql):
        with self.assertRaises(QueryError):
            parse(sql)

    def test_empty_queries(self):
        for sql in ("", "   ", "\n\t"):
            self.assert_query_error(sql)

    def test_missing_pieces(self):
        for sql in (
            "FROM t",
            "SELECT",
            "SELECT a",
            "SELECT a FROM",
            "SELECT FROM t",
            "SELECT a FROM t WHERE",
            "SELECT a FROM t HAVING",
        ):
            self.assert_query_error(sql)

    def test_trailing_commas(self):
        for sql in (
            "SELECT a, FROM t",
            "SELECT a FROM t GROUP BY a,",
            "SELECT a FROM t ORDER BY a,",
            "SELECT a FROM t WHERE x IN (1,)",
            "SELECT f(a,) FROM t",
        ):
            self.assert_query_error(sql)

    def test_star_must_be_alone(self):
        for sql in ("SELECT *, a FROM t", "SELECT * AS x FROM t"):
            self.assert_query_error(sql)

    def test_keyword_cannot_be_unquoted_alias_or_table(self):
        for sql in (
            "SELECT a AS FROM t",
            "SELECT a FROM SELECT",
        ):
            self.assert_query_error(sql)

    def test_bad_clauses(self):
        for sql in (
            "SELECT a FROM t GROUP a",
            "SELECT a FROM t ORDER a",
            "SELECT a FROM t WHERE x IS",
            "SELECT a FROM t WHERE x IS NOT 3",
            "SELECT a FROM t WHERE x NOT 3",
            "SELECT a FROM t WHERE x BETWEEN 1 OR 2",
            "SELECT a FROM t WHERE x IN ()",
        ):
            self.assert_query_error(sql)

    def test_bad_limits(self):
        for sql in (
            "SELECT a FROM t LIMIT",
            "SELECT a FROM t LIMIT -1",
            "SELECT a FROM t LIMIT +1",
            "SELECT a FROM t LIMIT 1.5",
            "SELECT a FROM t LIMIT '1'",
            "SELECT a FROM t LIMIT x",
            "SELECT a FROM t OFFSET 1",
            "SELECT a FROM t LIMIT 1 OFFSET",
            "SELECT a FROM t LIMIT 1 OFFSET -2",
            "SELECT a FROM t LIMIT 1 OFFSET 2.5",
        ):
            self.assert_query_error(sql)

    def test_extra_tokens(self):
        for sql in (
            "SELECT a FROM t; extra",
            "SELECT a FROM t;;",
            "SELECT a FROM t WHERE a = 1 WHERE b = 2",
            "SELECT a FROM t HAVING a > 1 GROUP BY a",
            "SELECT a FROM t garbage",
        ):
            self.assert_query_error(sql)

    def test_lexer_errors_reach_parser_as_query_error(self):
        for sql in (
            "SELECT 'abc FROM t",
            'SELECT "abc FROM t',
            "SELECT a & b FROM t",
        ):
            self.assert_query_error(sql)

    def test_chained_comparisons(self):
        for sql in (
            "SELECT a FROM t WHERE a = b = c",
            "SELECT a FROM t WHERE a < b IS NULL",
            "SELECT a FROM t WHERE a IN (1) IN (2)",
        ):
            self.assert_query_error(sql)


